    if (!r)
      return fail4(404, "ROOM_UNAVAILABLE");
    if (!db.query("SELECT 1 FROM woe_members WHERE room_id=? AND player_id=?").get(id, host))
      return fail4(404, "ROOM_UNAVAILABLE");
    if (r.host_id !== host)
      return fail4(403, "HOST_REQUIRED");
