    const events2 = gap ? [] : db.query("SELECT seq,event_json FROM woe_match_events WHERE match_id=? AND seq>? ORDER BY seq LIMIT ?").all(r.match_id, after, PAGE).map((x) => ({ seq: x.seq, ...JSON.parse(x.event_json) }));
